import flatpickr from 'flatpickr';
import { Dutch } from 'flatpickr/dist/l10n/nl';
import rangePlugin from 'flatpickr/dist/plugins/rangePlugin';
export const initDateTimePicker = (el) => {
    const { before, after, maxDate, minDate, readonly } = el.dataset;
    if (readonly) {
        el.readOnly = true;
        return;
    }
    const defaultOpts = {
        locale: Dutch,
        enableTime: true,
        time_24hr: true,
        minDate,
        maxDate,
    };
    // Als after is gezet, dan zorgt before dat deze datetimepicker geinitialiseerd wordt.
    if (after) {
        return;
    }
    // rangePlugin initialiseerd ook de andere input.
    if (before) {
        flatpickr(el, Object.assign(Object.assign({}, defaultOpts), { plugins: [rangePlugin({ input: `#${before}` })] }));
        return;
    }
    flatpickr(el, defaultOpts);
};
export const initDatePicker = (el) => {
    const { readonly, minDate, maxDate } = el.dataset;
    if (readonly) {
        el.readOnly = true;
        return;
    }
    flatpickr(el, {
        locale: Dutch,
        minDate,
        maxDate,
    });
};
